shared/worker-rate-limits.html:
{% set rate_user = identity if identity is defined else request.state.user %}
{% set rate_limit_url = ('/admin/workers/' ~ worker.id ~ '/rate-limits') if page in ['overview', 'admin_workers'] and rate_user.role in ['admin', 'superadmin'] else ('/user/workers/' ~ worker.id ~ '/rate-limits') %}
<div class="worker-rate-limits" data-rate-limits="{{ rate_limit_url }}" data-logged-in="{{ 'true' if worker.auth_mode and worker.failure_kind != 'logged_out' else 'false' }}"><input type="hidden" name="csrf_token" value="{{ csrf_token }}"><div data-rate-content aria-live="polite">{{ t('读取中…') if worker.auth_mode and worker.failure_kind != 'logged_out' else t('未登录') }}</div></div>
